// Generated data for dacrender: the nine standard voices compiled in, as
// the voice files of ../voices/lib/standard.lib hold them, and the
// device's gain table.

#define LIB_PITCHES 64
#define LIB_VOICES 9
#define LIB_GAINS 4096

// A voice: its name, sample period, mode (0 a table, 1 a sample), the
// envelope's latch values, the timbres' stride and thresholds, a
// sample's end and loop (0 for a table), its file's version, zone 6's
// block (-1: none), the step and the block of every pitch, and its
// blocks: lengthsP[0..nBlocks-1] words, one after another in wordsP.
typedef struct
{
    const char *nameP;
    int n;
    int sample;
    int start;
    int peak;
    int attack;
    int decay;
    int sustain;
    int release;
    int stride;
    int thresholds[3];
    int end;
    int loop;
    int version;
    int zone6;
    int steps[LIB_PITCHES];
    int zones[LIB_PITCHES];
    int nBlocks;
    const int *lengthsP;
    const unsigned long *wordsP;
} LibVoice;

